// Euclid's algorithm: repeatedly replace (x, y) with (y, x % y) until y is 0.
fn gcd(a, b) {
    let x = a;
    let y = b;
    while (y != 0) {
        let t = y;
        y = x % y;
        x = t;
    }
    return x;
}

