// Integer halving for even n (n < 32768), using only int arithmetic.
// Greedy binary subtraction: subtract 2*p whenever it fits, adding p to h.
fn half(n) {
    let r = n;
    let h = 0;
    if (r >= 16384) { r -= 16384; h += 8192; }
    if (r >= 8192)  { r -= 8192;  h += 4096; }
    if (r >= 4096)  { r -= 4096;  h += 2048; }
    if (r >= 2048)  { r -= 2048;  h += 1024; }
    if (r >= 1024)  { r -= 1024;  h += 512; }
    if (r >= 512)   { r -= 512;   h += 256; }
    if (r >= 256)   { r -= 256;   h += 128; }
    if (r >= 128)   { r -= 128;   h += 64; }
    if (r >= 64)    { r -= 64;    h += 32; }
    if (r >= 32)    { r -= 32;    h += 16; }
    if (r >= 16)    { r -= 16;    h += 8; }
    if (r >= 8)     { r -= 8;     h += 4; }
    if (r >= 4)     { r -= 4;     h += 2; }
    if (r >= 2)     { r -= 2;     h += 1; }
    return h;
}

