fn r2r(n) {
    let m = n / 1000;
    let c = (n % 1000) / 100;
    let x = (n % 100) / 10;
    let v = n % 10;

    let roman = "";
    if (m > 0) {
        roman += "M" * m;
    }
    if (c > 0) {
        if (c == 9) {
            roman += "CM";
        } else {
            roman += "D" * (c - (c == 5));
            if (c < 5) {
                roman += "C" * Math.floor((c - 1) / 10);
            }
        }
    }
    if (x > 0) {
        if (x == 9) {
            roman += "XC";
        } else {
            roman += "L" * (x - (x == 5));
            if (x < 5) {
                roman += "X" * Math.floor((x - 1) / 10);
            }
        }
    }
    if (v > 0) {
        if (v == 9) {
            roman += "IX";
        } else {
            roman += "V" * (v - (v == 5));
            if (v < 5) {
                roman += "I" * Math.floor((v - 1) / 10);
            }
        }
    }
    return roman;
}
